const $=id=>document.getElementById(id),fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:4}).format(n),unit=name=>itemUnits[name]||'items';
const machineName=(name,count)=>count===1?name:name.startsWith('Miner Mk.')?name.replace('Miner','Miners'):name.endsWith('y')?name.slice(0,-1)+'ies':name+'s';
const items=[...new Set(recipes.map(r=>r.item))].sort();
items.forEach(item=>$('item').add(new Option(item,item)));$('item').add(new Option('Custom recipe…','custom'));$('item').value='Reinforced Iron Plate';
$('coverage').textContent=`${recipeMetadata.total} wiki recipes · ${recipeMetadata.alternate} alternate · ${items.length} outputs`;$('checkedDate').textContent=recipeMetadata.checked;
function selectItem(){const custom=$('item').value==='custom';$('custom').hidden=!custom;$('recipe').disabled=custom;$('recipe').replaceChildren();recipes.filter(r=>r.item===$('item').value).forEach(r=>{const type=r.manual?'Manual':r.alternate?'Alternate':'Standard';const suffix=[r.seasons.length?'FICSMAS':'',!r.primary?'by-product':''].filter(Boolean).join(', ');$('recipe').add(new Option(`${type}: ${r.name}${suffix?' ('+suffix+')':''}`,r.id));});if(custom)$('recipe').add(new Option('Enter a wiki recipe rate','custom'));render();}
function getRecipe(){return $('item').value==='custom'?{item:'Custom output',name:'Custom recipe',machine:$('customMachine').value,rate:Number($('base').value),inputs:{},outputs:{},seasons:[],overclockable:true}:recipes.find(r=>r.id===$('recipe').value);}
function calculate(rate,target,clock,allowLarge=false){if(!Number.isFinite(rate)||rate<=0||!Number.isFinite(target)||target<0||(target>1e9&&!allowLarge)||!Number.isFinite(clock)||clock<1||clock>250)throw Error('Enter a valid target (0–1 billion), a positive recipe rate, and a clock speed from 1% to 250%.');const per=rate*clock/100,exact=target/per,count=target===0?0:Math.max(1,Math.ceil(exact-Number.EPSILON*Math.max(1,exact)*4));return{per,count,capacity:count*per,balanced:count?target/(count*rate)*100:0,target};}
function rows(container,entries,scale,perMinute){container.replaceChildren();Object.entries(entries).forEach(([name,rate])=>{const row=document.createElement('div');row.className='input-row';const label=document.createElement('span');label.textContent=name;const value=document.createElement('strong');value.textContent=`${fmt(rate*scale)} ${unit(name)==='m³'?'m³ ':''}${perMinute?'/ min':'/ craft'}`;row.append(label,value);container.append(row);});}
function setMode(r){const manual=!!r.manual,locked=manual||!r.overclockable;['amount','minutes','mode'].forEach(id=>$(id).disabled=manual);['clock','slider'].forEach(id=>$(id).disabled=locked);document.querySelectorAll('[data-clock]').forEach(b=>b.disabled=locked);$('machineCaption').textContent=manual?'manual crafting only':'machines to build';$('metrics').hidden=manual;$('utilization').hidden=manual;$('inputDescription').textContent=manual?'Ingredients consumed in one completed craft.':'For your target output, with machines tuned to match.';$('inputNote').textContent=manual?'This recipe cannot run in a production machine.':r.name==='Custom recipe'?'Input ingredients are not calculated for custom recipes.':'Supply these ingredients continuously. All recipe outputs must be removed to prevent the machine from stopping.';$('recipeBadge').textContent=manual?'MANUAL ONLY':r.name==='Custom recipe'?'CUSTOM RECIPE':r.alternate?'ALTERNATE RECIPE':'STANDARD RECIPE';$('source').href='https://satisfactory.wiki.gg/wiki/'+(r.name==='Custom recipe'?'Recipes':encodeURIComponent(r.item.replaceAll(' ','_')));$('recipeNote').textContent=[manual?r.machine:`${r.machine} · ${fmt(r.rate)} ${unit(r.item)} / min at 100%`,r.seasons.length?'FICSMAS seasonal recipe':'',r.unlock||''].filter(Boolean).join(' · ');$('byproducts').hidden=manual||Object.keys(r.outputs).filter(n=>n!==r.item).length===0;}
function render(){if(noOutputs){renderEmptyOutputs();return null;}document.querySelector('.controls').hidden=false;document.querySelector('.first-output-details').hidden=false;try{updateTargetLabels();const r=getRecipe();setMode(r);if(r.manual){$('error').textContent='';document.body.classList.remove('invalid');$('count').textContent='—';$('machine').textContent=r.machine;$('summary').textContent='This item must be crafted by hand. No automated machine count applies.';$('tuning').textContent='Clock speed and automated production targets do not apply. Choose another recipe or output item to calculate machines.';$('clockTag').textContent='NOT APPLICABLE';rows($('inputs'),r.inputs,r.duration/60,false);$('otherOutputs').replaceChildren();updateGraphics(r);window.currentResult={recipe:r.name,item:r.item,manual:true,machine:r.machine};renderProductionChain(r,0);return window.currentResult;}
if(!$('amount').value||!$('clock').value)throw Error('Enter your output target and clock speed.');const batch=$('mode').value==='batch',u=unit(r.item);$('timeField').hidden=!batch;$('amountLabel').textContent=batch?(u==='m³'?'Total volume (m³)':'Total items'):`${u==='m³'?'Volume (m³)':'Items'} per minute`;$('mode').options[0].textContent=`Continuous • ${u} per minute`;const minutes=Number($('minutes').value);if(batch&&(!Number.isFinite(minutes)||minutes<=0))throw Error('Enter a completion time greater than zero.');const clock=r.overclockable?Number($('clock').value):100,target=Number($('amount').value)/(batch?minutes:1),v=calculate(r.rate,target,clock);$('error').textContent='';document.body.classList.remove('invalid');$('slider').value=clock;if(!r.overclockable)$('clock').value=100;$('clockTag').textContent=clock>100?'OVERCLOCKED':clock<100?'UNDERCLOCKED':'STANDARD';document.querySelectorAll('[data-clock]').forEach(b=>b.classList.toggle('active',Number(b.dataset.clock)===clock));$('count').textContent=fmt(v.count);$('machine').textContent=machineName(r.machine,v.count);$('summary').textContent=`${fmt(target)} ${u} / min requested · ${fmt(clock)}% clock speed`;$('perMachine').textContent=fmt(v.per);$('capacity').textContent=fmt(v.capacity);$('spare').textContent=fmt(Math.max(0,v.capacity-target));document.querySelectorAll('.metrics small').forEach(e=>e.textContent=u+' / min');const util=v.capacity?target/v.capacity*100:0;$('util').textContent=fmt(util)+'%';$('bar').style.width=util+'%';$('tuning').textContent=!v.count?'No machines are needed for a zero target.':v.balanced<1?'Your target is below 1% clock speed. Run one machine intermittently at the 1% minimum.':`Set all ${fmt(v.count)} ${machineName(r.machine,v.count).toLowerCase()} to approximately ${fmt(v.balanced)}% clock speed to produce ${fmt(target)} ${u} / min with no surplus.`;rows($('inputs'),r.inputs,target/r.rate,true);rows($('otherOutputs'),Object.fromEntries(Object.entries(r.outputs).filter(([n])=>n!==r.item)),target/r.rate,true);updateGraphics(r);window.currentResult={...v,recipe:r.name,item:r.item,machine:r.machine,clock};renderProductionChain(r,target);return window.currentResult;}catch(e){$('error').textContent=e.message;document.body.classList.add('invalid');window.currentResult=null;window.currentChain=null;$('productionChain').hidden=true;renderFactorySummary(null);return null;}}
$('item').addEventListener('change',selectItem);['recipe','mode','amount','minutes','clock','base','customMachine'].forEach(id=>$(id).addEventListener('input',render));$('slider').addEventListener('input',()=>{$('clock').value=$('slider').value;render();});document.querySelectorAll('[data-clock]').forEach(b=>b.addEventListener('click',()=>{$('clock').value=b.dataset.clock;render();}));initUnifiedLayout();initProductionChain();initMultipleOutputs();selectItem();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_machine_calculator',description:'Choose an automated wiki recipe, desired output, production rate and clock speed. Fluids use cubic metres per minute.',inputSchema:{type:'object',properties:{recipe:{type:'string',enum:[...new Set(recipes.filter(r=>!r.manual).map(r=>r.name))]},outputItem:{type:'string',description:'Optional output or by-product; defaults to main product.'},itemsPerMinute:{type:'number',minimum:0,maximum:1e9},clockPercent:{type:'number',minimum:1,maximum:250}},required:['recipe','itemsPerMinute','clockPercent'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const r=recipes.find(r=>!r.manual&&r.name===input.recipe&&(input.outputItem?r.item===input.outputItem:r.primary));if(!r)throw Error('Unknown automated recipe or output');calculate(r.rate,input.itemsPerMinute,input.clockPercent);if(!r.overclockable&&input.clockPercent!==100)throw Error('This machine does not support overclocking');noOutputs=false;$('item').value=r.item;selectItem();$('recipe').value=r.id;$('mode').value='rate';$('amount').value=input.itemsPerMinute;$('clock').value=input.clockPercent;const result=render();return {...result,chain:compactChain(window.currentChain)};}})).catch(()=>{});}catch{}}

function initUnifiedLayout(){
 const panel=document.querySelector('.multi-target-panel'),controls=document.querySelector('.controls');
 controls.querySelector('.section-title').remove();
 const settings=document.createElement('div');settings.className='shared-target-settings';
 const wrap=(label,control)=>{const d=document.createElement('div');d.append(label,control);return d;};
 settings.append(wrap(document.querySelector('label[for="mode"]'),$('mode')),$('timeField'));
 panel.insertBefore(settings,$('additionalTargetRows'));
 const row=document.createElement('div');row.className='primary-target-grid';
 document.querySelector('label[for="clock"]').textContent='Clock speed (%)';
 row.append($('itemPreview'),wrap(document.querySelector('label[for="item"]'),$('item')),wrap(document.querySelector('label[for="recipe"]'),$('recipe')),wrap($('amountLabel'),$('amount')),wrap(document.querySelector('label[for="clock"]'),$('clock')));
 const remove=document.createElement('button');remove.id='removeFirstOutput';remove.type='button';remove.className='remove-target';remove.textContent='Remove';remove.setAttribute('aria-label','Remove first output');remove.addEventListener('click',removeFirstOutput);row.append(remove);
 controls.replaceChildren(row,$('recipeNote'),$('custom'),$('error'));
 panel.insertBefore(controls,$('additionalTargetRows'));
 // Keep existing calculator hooks available without duplicating the target controls.
 const hooks=document.createElement('div');hooks.hidden=true;hooks.append(document.createElement('span'));hooks.firstChild.id='clockTag';
 const slider=document.createElement('input');slider.id='slider';slider.type='range';slider.min=1;slider.max=250;hooks.append(slider);controls.append(hooks);
 const detail=document.createElement('details');detail.className='first-output-details';const summary=document.createElement('summary');summary.textContent='First output: recipe details';detail.append(summary,document.querySelector('.tuning'),document.querySelector('.ingredients'));document.querySelector('.results').append(detail);
}
function renderFactorySummary(plan){
 const automated=!getRecipe().manual&&getRecipe().name!=='Custom recipe';
 $('allMachineCards').replaceChildren();$('allMachineCards').hidden=!automated;
 document.querySelector('.machine-visual').hidden=automated;
 $('mainOnlyNote').hidden=true;
 if(!automated){$('resultHeading').textContent='MAIN OUTPUT · FINAL STAGE';return;}
 $('resultHeading').textContent='MAIN OUTPUT · ALL MACHINES';$('metrics').hidden=true;$('utilization').hidden=true;
 $('count').textContent=plan?fmt(plan.total):'—';$('machine').textContent='Total machines';$('machineCaption').textContent='for all outputs and their inputs';$('recipeBadge').textContent=plan?plan.targets.length+' OUTPUT'+(plan.targets.length===1?'':'S'):'CHECK TARGETS';
 $('summary').textContent=plan?plan.targets.map(t=>t.item+': '+fmt(t.target)+' '+unit(t.item)+'/min @ '+fmt(t.clock)+'%').join(' · '):'Correct the target settings to calculate your factory.';
 if(!plan)return;
 for(const [name,count] of Object.entries(plan.totals).sort(([a],[b])=>a.localeCompare(b))){const card=document.createElement('div');card.className='all-machine-card';if(wikiImages[name]){const img=document.createElement('img');img.width=64;img.height=64;card.append(img);wikiImage(name,img);}const text=document.createElement('div'),strong=document.createElement('strong'),label=document.createElement('span');strong.textContent=fmt(count);label.textContent=machineName(name,count);text.append(strong,label);card.append(text);$('allMachineCards').append(card);}
 if(plan.external){const note=document.createElement('p');note.textContent='Some inputs require external supply. See the full production chain below.';$('allMachineCards').append(note);}
}
